        q.pop();
        int x = current.first;
        int y = current.second;

        for (auto& dir : directions) {
            int newX = x + dir[0];
            int newY = y + dir[1];
            if (newX >= 0 && newX < rows && newY >= 0 && newY < cols && maze[newX][newY] == 0 && distance[newX][newY] == INT_MAX) {
