class Solution {
    public int largestPathValue(String colors, int[][] edges) {
        int n = colors.length();
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }

        int[] inDegrees = new int[n];
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            inDegrees[e[1]]++;
        }

        int[][] colorCounts = new int[n][26];
        Deque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (inDegrees[i] == 0) {
                queue.addLast(i);
            }
