class IntervalOverlapChecker {
    public int countOverlappingIntervals(List<int[]> intervals) {
        if (intervals == null || intervals.isEmpty()) {
            return 0;
        }

        // Sort intervals based on the start time
        intervals.sort((a, b) -> Integer.compare(a[0], b[0]));

        int count = 0;
        int[] currentInterval = intervals.get(0);
        for (int i = 1; i < intervals.size(); i++) {
            int[] nextInterval = intervals.get(i);
            if (nextInterval[0] <= currentInterval[1]) {
                // Overlapping intervals
                count++;
                // Update the current interval to the one with the latest end time
                currentInterval[1] = Math.max(currentInterval[1], nextInterval[1]);
            } else {
                // No overlap, update the current interval
                currentInterval = nextInterval;
            }
        }

        return count;
    }
}
```

