    int n = arr.size();
    vector<int> lengthLeft(n + 2, 0), lengthRight(n + 2, 0);
    int count = 0, result = -1;

    for (int i = 0; i < n; ++i) {
        int pos = arr[i];
        int leftLength = lengthRight[pos - 1];
        int rightLength = lengthLeft[pos + 1];
        int newLength = leftLength + rightLength + 1;

