public int longestPalindromicSubsequence(String s) {
    int n = s.length();
    if (n == 0) return 0;

    int[][] dp = new int[n][n];

    for (int i = 0; i < n; i++) {
        dp[i][i] = 1;
    }

    for (int cl = 2; cl <= n; cl++) {
        for (int i = 0; i < n - cl + 1; i++) {
            int j = i + cl - 1;
            if (s.charAt(i) == s.charAt(j) && cl == 2) {
                dp[i][j] = 2;
